     1→/**
     2→ * FreeLang Nexus - 런타임 실행기
     3→ * 생성된 C/Python 코드를 컴파일하고 실행
     4→ */
     5→
     6→import { execSync, spawnSync, SpawnSyncReturns } from 'child_process';
     7→import * as fs from 'fs';
     8→import * as path from 'path';
     9→import * as os from 'os';
    10→import { CodegenResult } from '../codegen/nexus-codegen';
    11→
    12→export interface RunResult {
    13→  cOutput: string;      // C 실행 결과 (stdout)
    14→  pythonOutput: string; // Python 실행 결과 (stdout)
    15→  errors: string[];     // 컴파일/실행 에러 목록
    16→}
    17→
    18→export class NexusRunner {
    19→  private ccCache: string | null = null;
    20→
    21→  /**
    22→   * CodegenResult 전체 실행 (C + Python 모두)
    23→   */
    24→  run(result: CodegenResult): RunResult {
    25→    const errors: string[] = [];
    26→    let cOutput = '';
    27→    let pythonOutput = '';
    28→
    29→    // Rust/Go/Julia externLibs 사전 빌드 → linkFlags에 추가
    30→    const extraFlags: string[] = [];
    31→    for (const lib of (result.externLibs || [])) {
    32→      if (lib.lang === 'rust') {
    33→        const alias = lib.alias || this.safeAlias(lib.package);
    34→        const workDir = this.tmpFile('_rust_' + alias);
    35→        const soPath = NexusRunner.buildRustLib(lib.package, alias, workDir);
    36→        if (soPath) {
    37→          extraFlags.push(`-L${path.dirname(soPath)}`, `-l${alias}`);
    38→        } else {
    39→          errors.push(`Rust 빌드 실패: ${lib.package} (cargo build --release)`);
    40→        }
    41→      } else if (lib.lang === 'go') {
    42→        const alias = lib.alias || this.safeAlias(lib.package);
    43→        const workDir = this.tmpFile('_go_' + alias);
    44→        const soPath = NexusRunner.buildGoLib(lib.package, alias, workDir);
    45→        if (soPath) {
    46→          extraFlags.push(`-L${path.dirname(soPath)}`, `-l${alias}`);
    47→        } else {
    48→          errors.push(`Go 빌드 실패: ${lib.package} (go build -buildmode=c-shared)`);
    49→        }
    50→      } else if (lib.lang === 'julia') {
    51→        const juliaFlags = NexusRunner.getJuliaCFlags();
    52→        extraFlags.push(...juliaFlags, '$(julia-config --ldflags --ldlibs)');
    53→      }
    54→    }
    55→
    56→    // C 코드 실행 (linkFlags + extraFlags 자동 전달)
    57→    if (result.c && result.c.trim()) {
    58→      try {
    59→        cOutput = this.runC(result.c, [...(result.linkFlags || []), ...extraFlags]);
    60→      } catch (e) {
    61→        errors.push(`C 컴파일/실행 에러: ${(e as Error).message}`);
    62→      }
    63→    }
    64→
    65→    // Python 코드 실행
    66→    if (result.python && result.python.trim()) {
    67→      try {
    68→        pythonOutput = this.runPython(result.python);
    69→      } catch (e) {
    70→        errors.push(`Python 실행 에러: ${(e as Error).message}`);
    71→      }
    72→    }
    73→
    74→    return { cOutput, pythonOutput, errors };
    75→  }
    76→
    77→  /**
    78→   * C 코드 실행
    79→   * 임시 파일 → 컴파일 → 실행 → 정리
    80→   *
    81→   * @param linkFlags  추가 링크 플래그 (['-lsqlite3', '-lm'] 등)
    82→   */
    83→  runC(cCode: string, linkFlags: string[] = []): string {
    84→    const cFile = this.tmpFile('.c');
    85→    const binFile = this.tmpFile('');
    86→
    87→    try {
    88→      // C 코드를 임시 파일에 저장
    89→      fs.writeFileSync(cFile, cCode, 'utf-8');
    90→
    91→      // 컴파일 (gcc 또는 clang)
    92→      const cc = this.detectCC();
    93→      // $(python3-config --ldflags) 등을 실제 플래그로 확장
    94→      const resolvedFlags = this.resolveShellFlags(linkFlags);
    95→      // Python.h 필요 시 include 경로 추가
    96→      const hasPython = linkFlags.some(f => f.includes('python3-config'));
    97→      const cflagsExtra = hasPython ? NexusRunner.getPythonCFlags() : [];
    98→      const flagStr = [...cflagsExtra, ...resolvedFlags].join(' ');
    99→      try {
   100→        execSync(`${cc} -o ${binFile} ${cFile} ${flagStr}`, {
   101→          stdio: 'pipe',
   102→          encoding: 'utf-8',
   103→        });
   104→      } catch (e) {
   105→        throw new Error(`컴파일 실패 (${cc}): ${(e as Error).message}`);
   106→      }
   107→
   108→      // 바이너리 실행
   109→      const result: SpawnSyncReturns<string> = spawnSync(binFile, [], {
   110→        encoding: 'utf-8',
   111→        stdio: 'pipe',
   112→      });
   113→
   114→      if (result.error) {
   115→        throw new Error(`실행 실패: ${result.error.message}`);
   116→      }
   117→
   118→      return result.stdout || '';
   119→    } finally {
   120→      // 임시 파일 정리
   121→      try {
   122→        if (fs.existsSync(cFile)) fs.unlinkSync(cFile);
   123→        if (fs.existsSync(binFile)) fs.unlinkSync(binFile);
   124→      } catch (e) {
   125→        // 정리 실패는 무시
   126→      }
   127→    }
   128→  }
   129→
   130→  /**
   131→   * Python 코드 실행
   132→   * 임시 파일 → python3 실행 → 정리
   133→   */
   134→  runPython(pyCode: string): string {
   135→    const pyFile = this.tmpFile('.py');
   136→
   137→    try {
   138→      // Python 코드를 임시 파일에 저장
   139→      fs.writeFileSync(pyFile, pyCode, 'utf-8');
   140→
   141→      // python3 실행
   142→      const result: SpawnSyncReturns<string> = spawnSync('python3', [pyFile], {
   143→        encoding: 'utf-8',
   144→        stdio: 'pipe',
   145→      });
   146→
   147→      if (result.error) {
   148→        throw new Error(`Python 실행 실패: ${result.error.message}`);
   149→      }
   150→
   151→      return result.stdout || '';
   152→    } finally {
   153→      // 임시 파일 정리
   154→      try {
   155→        if (fs.existsSync(pyFile)) fs.unlinkSync(pyFile);
   156→      } catch (e) {
   157→        // 정리 실패는 무시
   158→      }
   159→    }
   160→  }
   161→
   162→  /**
   163→   * $(python3-config --ldflags) 같은 shell expansion 플래그를 실제 값으로 변환
   164→   * 실패 시 해당 플래그를 제외
   165→   */
   166→  private resolveShellFlags(flags: string[]): string[] {
   167→    const result: string[] = [];
   168→    for (const f of flags) {
   169→      if (f.startsWith('$(') && f.endsWith(')')) {
   170→        const cmd = f.slice(2, -1); // 'python3-config --ldflags'
   171→        try {
   172→          // python3-config --ldflags는 --embed 옵션이 있어야 -lpython3.x 포함
   173→          const embedCmd = cmd.includes('python3-config') && cmd.includes('--ldflags')
   174→            ? cmd + ' --embed'
   175→            : cmd;
   176→          let out: string;
   177→          try {
   178→            out = execSync(embedCmd, { stdio: 'pipe', encoding: 'utf-8' }).trim();
   179→          } catch {
   180→            out = execSync(cmd, { stdio: 'pipe', encoding: 'utf-8' }).trim();
   181→          }
   182→          result.push(...out.split(/\s+/).filter(Boolean));
   183→        } catch (e) {
   184→          // 실행 실패 시 해당 플래그 제외
   185→        }
   186→      } else {
   187→        result.push(f);
   188→      }
   189→    }
   190→    return result;
   191→  }
   192→
   193→  /**
   194→   * python3 C include 플래그 반환 (Python.h 포함 경로)
   195→   */
   196→  static getPythonCFlags(): string[] {
   197→    try {
   198→      const out = execSync('python3-config --includes', { stdio: 'pipe', encoding: 'utf-8' }).trim();
   199→      return out.split(/\s+/).filter(Boolean);
   200→    } catch (e) {
   201→      return [];
   202→    }
   203→  }
   204→
   205→  /**
   206→   * julia C include 플래그 반환 (julia.h 포함 경로)
   207→   */
   208→  static getJuliaCFlags(): string[] {
   209→    try {
   210→      const out = execSync('julia-config --cflags', { stdio: 'pipe', encoding: 'utf-8' }).trim();
   211→      return out.split(/\s+/).filter(Boolean);
   212→    } catch (e) {
   213→      return [];
   214→    }
   215→  }
   216→
   217→  /**
   218→   * Rust 크레이트를 c-shared 라이브러리로 빌드
   219→   * workDir에 Cargo.toml + src/lib.rs 생성 후 cargo build --release
   220→   * 성공 시 .so 경로 반환, 실패 시 null
   221→   */
   222→  static buildRustLib(pkg: string, alias: string, workDir: string): string | null {
   223→    try {
   224→      const cargoToml = `[package]
   225→name = "${alias}"
   226→version = "0.1.0"
   227→edition = "2021"
   228→
   229→[lib]
   230→crate-type = ["cdylib"]
   231→
   232→[dependencies]
   233→${pkg} = "*"
   234→`;
   235→      const libRs = `// Auto-generated by FreeLang Nexus
   236→pub use ${alias.replace(/-/g,'_')}::*;
   237→`;
   238→      fs.mkdirSync(path.join(workDir, 'src'), { recursive: true });
   239→      fs.writeFileSync(path.join(workDir, 'Cargo.toml'), cargoToml);
   240→      fs.writeFileSync(path.join(workDir, 'src', 'lib.rs'), libRs);
   241→      execSync('cargo build --release', { cwd: workDir, stdio: 'pipe' });
   242→      const soPath = path.join(workDir, 'target', 'release', `lib${alias}.so`);
   243→      if (fs.existsSync(soPath)) return soPath;
   244→      return null;
   245→    } catch (e) {
   246→      return null;
   247→    }
   248→  }
   249→
   250→  /**
   251→   * Go 패키지를 c-shared 라이브러리로 빌드
   252→   * workDir에 go.mod + main.go 생성 후 go build -buildmode=c-shared
   253→   * 성공 시 .so 경로 반환, 실패 시 null
   254→   */
   255→  static buildGoLib(pkg: string, alias: string, workDir: string): string | null {
   256→    try {
   257→      const goMod = `module freelang_${alias}
   258→go 1.21
   259→require ${pkg} v0.0.0-00010101000000-000000000000
   260→`;
   261→      const mainGo = `package main
   262→
   263→import "C"
   264→import _ "${pkg}"
   265→
   266→func main() {}
   267→`;
   268→      fs.mkdirSync(workDir, { recursive: true });
   269→      fs.writeFileSync(path.join(workDir, 'go.mod'), goMod);
   270→      fs.writeFileSync(path.join(workDir, 'main.go'), mainGo);
   271→      const soPath = path.join(workDir, `lib${alias}.so`);
   272→      const hPath = path.join(workDir, `lib${alias}.h`);
   273→      execSync(
   274→        `go build -buildmode=c-shared -o ${soPath} .`,
   275→        { cwd: workDir, stdio: 'pipe' }
   276→      );
   277→      if (fs.existsSync(soPath)) return soPath;
   278→      return null;
   279→    } catch (e) {
   280→      return null;
   281→    }
   282→  }
   283→
   284→  private safeAlias(pkg: string): string {
   285→    const last = pkg.split(/[\/\-\.]/).filter(Boolean).pop() || pkg;
   286→    return last.replace(/[^a-zA-Z0-9_]/g, '_');
   287→  }
   288→
   289→  /**
   290→   * 컴파일러 감지 (gcc 또는 clang)
   291→   * Termux 환경에서는 clang을 기본으로 사용하는 경우가 많음
   292→   */
   293→  private detectCC(): string {
   294→    if (this.ccCache) {
   295→      return this.ccCache;
   296→    }
   297→
   298→    // 먼저 gcc 확인
   299→    try {
   300→      execSync('gcc --version', { stdio: 'pipe' });
   301→      this.ccCache = 'gcc';
   302→      return 'gcc';
   303→    } catch (e) {
   304→      // gcc 실패
   305→    }
   306→
   307→    // clang 확인
   308→    try {
   309→      execSync('clang --version', { stdio: 'pipe' });
   310→      this.ccCache = 'clang';
   311→      return 'clang';
   312→    } catch (e) {
   313→      // clang 실패
   314→    }
   315→
   316→    // 기본값: gcc (찾기 실패해도 시도)
   317→    this.ccCache = 'gcc';
   318→    return 'gcc';
   319→  }
   320→
   321→  /**
   322→   * 임시 파일 경로 생성
   323→   * /tmp/nexus_TIMESTAMP.ext 형식
   324→   */
   325→  private tmpFile(ext: string): string {
   326→    const timestamp = Date.now();
   327→    const random = Math.random().toString(36).substring(2, 8);
   328→    const filename = `nexus_${timestamp}_${random}${ext}`;
   329→    return path.join(os.tmpdir(), filename);
   330→  }
   331→}
   332→

