   271→}
   272→
   273→/**
   274→ * 프로그램 (최상위 노드)
   275→ */
   276→export interface Program {
   277→  type: 'Program';
   278→  body: Array<VFunction | PyFunction | StructDef | Statement | ExternCall>;
   279→}
