     1→/**
     2→ * FreeLang Nexus - 통합 Parser
     3→ * V 모드 + Python 모드 함수를 혼합하여 파싱
     4→ */
     5→
     6→import { Token, TokenType } from '../lexer/token';
     7→import * as AST from './ast';
     8→
     9→export class NexusParser {
    10→  private tokens: Token[];
    11→  private pos: number = 0;
    12→
    13→  constructor(tokens: Token[]) {
    14→    this.tokens = tokens;
    15→  }
    16→
    17→  /**
    18→   * 파싱 진입점
    19→   */
    20→  parse(): AST.Program {
    21→    const body: Array<AST.VFunction | AST.PyFunction | AST.StructDef | AST.Statement | AST.ExternCall> = [];
    22→
    23→    while (!this.isAtEnd()) {
    24→      this.skipNewlines();
    25→      if (this.isAtEnd()) break;
    26→
    27→      const token = this.peek();
    28→
    29→      // @mode 마커는 스킵 (이미 렉서에서 처리됨)
    30→      if (token.type === TokenType.MODE_MARKER) {
    31→        this.advance();
    32→        continue;
    33→      }
    34→
    35→      // @call 디렉티브
    36→      if (token.type === TokenType.CALL_DIRECTIVE) {
    37→        const callNode = this.parseCallDirective();
    38→        if (callNode) body.push(callNode);
    39→        continue;
    40→      }
    41→
    42→      // 탑레벨 아이템 파싱
    43→      const item = this.parseTopLevel();
    44→      if (item) {
    45→        body.push(item);
    46→      }
    47→    }
    48→
    49→    return { type: 'Program', body };
    50→  }
    51→
    52→  /**
    53→   * @call 디렉티브 파싱
    54→   * 토큰 value: "@call python:numpy 1.24" 또는 "@call rust:rand as r"
    55→   *
    56→   * 문법: @call <lang>:<package> [<version>] [as <alias>]
    57→   */
    58→  private parseCallDirective(): AST.ExternCall | null {
    59→    const token = this.advance(); // CALL_DIRECTIVE 토큰 소비
    60→    const raw = token.value; // "@call python:numpy 1.24"
    61→
    62→    // "@call " 제거
    63→    const body = raw.slice('@call '.length).trim();
    64→
    65→    // lang:package 분리
    66→    const colonIdx = body.indexOf(':');
    67→    if (colonIdx === -1) return null;
    68→
    69→    const lang = body.slice(0, colonIdx).trim() as AST.ExternCall['lang'];
    70→    const rest = body.slice(colonIdx + 1).trim();
    71→
    72→    // "as alias" 분리
    73→    let alias: string | undefined;
    74→    let packageAndVersion = rest;
    75→    const asIdx = rest.search(/\s+as\s+/);
    76→    if (asIdx !== -1) {
    77→      alias = rest.slice(asIdx).replace(/\s+as\s+/, '').trim();
    78→      packageAndVersion = rest.slice(0, asIdx).trim();
    79→    }
    80→
    81→    // package와 version 분리 (마지막 공백 기준)
    82→    const parts = packageAndVersion.split(/\s+/);
    83→    const pkg = parts[0];
    84→    const version = parts.length > 1 ? parts[parts.length - 1] : undefined;
    85→
    86→    const supportedLangs = new Set(['python', 'rust', 'go', 'julia', 'js', 'c', 'cpp']);
    87→    if (!supportedLangs.has(lang)) return null;
    88→
    89→    return {
    90→      type: 'ExternCall',
    91→      lang,
    92→      package: pkg,
    93→      version,
    94→      alias,
    95→      line: token.line,
    96→      column: token.column,
    97→      mode: token.mode,
    98→    };
    99→  }
   100→

