     1→/**
     2→ * FreeLang Nexus - 코드 생성기
     3→ * AST → C 코드 (V 모드) + Python 코드 (Python 모드)
     4→ */
     5→
     6→import * as AST from '../parser/ast';
     7→
     8→export interface CodegenResult {
     9→  c: string;          // V 모드 함수들 → C 코드
    10→  python: string;     // Python 모드 함수들 → Python 코드
    11→  mixed: string;      // 두 코드 주석으로 구분 (디버그용)
    12→  linkFlags: string[]; // gcc 링크 플래그 (@call 에서 수집) e.g. ['-lsqlite3', '-lm']
    13→  externLibs: ExternLibInfo[]; // @call 지시문 요약
    14→}
    15→
    16→/** @call 지시문 하나의 요약 정보 */
    17→export interface ExternLibInfo {
    18→  lang: string;
    19→  package: string;
    20→  version?: string;
    21→  alias?: string;
    22→  linkFlags: string[];  // 이 언어/패키지에 필요한 링크 플래그
    23→  buildCmd?: string;    // 사전 빌드 명령 (Rust/Go 전용)
    24→}
    25→
    26→export class NexusCodegen {
    27→  private cLines: string[] = [];
    28→  private pyLines: string[] = [];
    29→  private indentLevel: number = 0;
    30→  private linkFlagsSet: Set<string> = new Set();
    31→  private externLibs: ExternLibInfo[] = [];
    32→  // 선언된 변수 추적 (스코프 스택) - 중복 선언 방지
    33→  private declaredVars: Set<string>[] = [new Set()];
    34→  // Python alias 맵: alias → { package, cVar }
    35→  // @call python:numpy as np → { 'np': { pkg: 'numpy', cVar: '__fl_py_mod_np' } }
    36→  private pyAliasMap: Map<string, { pkg: string; cVar: string }> = new Map();
    37→  // Python 마샬링 헬퍼 주입 여부
    38→  private pyHelpersInjected: boolean = false;
    39→
    40→  /**
    41→   * V 모드 내장 함수 처리
    42→   */
    43→  private readonly V_BUILTINS = new Set([
    44→    'println', 'print', 'len', 'to_string', 'int_cast',
    45→    // 수학
    46→    'abs', 'min', 'max', 'sqrt', 'pow', 'floor', 'ceil',
    47→    // 문자열
    48→    'str_len', 'str_contains', 'str_concat', 'str_eq',
    49→    // 타입 변환
    50→    'float_cast', 'bool_cast',
    51→  ]);
    52→
    53→  /**
    54→   * 프로그램 전체 코드 생성
    55→   */
    56→  generate(program: AST.Program): CodegenResult {
    57→    // @mode 마커는 무시하고 함수/문장만 처리
    58→    for (const item of program.body) {
    59→      const fnItem = item as any;
    60→      if (fnItem.type === 'ExternCall') {
    61→        this.genExternCall(fnItem as AST.ExternCall);
    62→      } else if (fnItem.type === 'VFunction') {
    63→        this.genVFunction(fnItem as AST.VFunction);
    64→      } else if (fnItem.type === 'PyFunction') {
    65→        this.genPyFunction(fnItem as AST.PyFunction);
    66→      } else if (fnItem.type === 'StructDef') {
    67→        this.genVStructDef(fnItem as AST.StructDef);
    68→        this.genPyStructDef(fnItem as AST.StructDef);
    69→      } else if (fnItem.type === 'Return' || fnItem.type === 'Assign' || fnItem.type === 'ExprStatement' || fnItem.type === 'MatchStatement') {
    70→        // 탑레벨 문장은 V 모드(C)로 처리
    71→        this.genVStatement(fnItem as AST.Statement);
    72→      }
    73→    }
    74→
    75→    const c = this.cLines.join('\n');
    76→    const python = this.pyLines.join('\n');
    77→
    78→    // mixed: 두 언어 코드를 주석으로 구분해서 출력 (확인용)
    79→    const mixed =
    80→      c && python
    81→        ? `/* ===== V (C) ===== */\n${c}\n\n/* ===== Python ===== */\n# (Not valid C, just for reference)\n${python}`
    82→        : c || python;
    83→
    84→    return {
    85→      c,
    86→      python,
    87→      mixed,
    88→      linkFlags: Array.from(this.linkFlagsSet),
    89→      externLibs: this.externLibs,
    90→    };
    91→  }
    92→
    93→  /**
    94→   * 실행 가능한 프로그램 생성
    95→   * C에는 #include + main() 추가, Python에는 if __name__ 추가
    96→   */
    97→  generateProgram(program: AST.Program): CodegenResult {
    98→    const base = this.generate(program);
    99→
   100→    // fn main()이 이미 있으면 int main() 추가하지 않음
   101→    const hasMain = program.body.some(
   102→      (n: any) => n.type === 'VFunction' && n.name === 'main'
   103→    );
   104→
   105→    // Python 모듈 자동 초기화 코드 삽입 (fn main 앞에 __attribute__((constructor)) 사용)
   106→    const pyInits = Array.from(this.pyAliasMap.keys())
   107→      .map(alias => `    __fl_py_init_${alias}();`)
   108→      .join('\n');
   109→    const pyFinalize = this.pyAliasMap.size > 0 ? '\n    Py_Finalize();' : '';
   110→
   111→    // main 래퍼: fn main()이 없을 때만 기본 main 추가
   112→    // fn main()이 있으면, Python init을 __attribute__((constructor))로 main 전에 실행
   113→    let mainWrapper = '';
   114→    if (!hasMain) {
   115→      const pyInitBlock = pyInits ? `\n${pyInits}` : '';
   116→      mainWrapper = `\nint main() {${pyInitBlock}${pyFinalize}\n    return 0;\n}\n`;
   117→    } else if (pyInits) {
   118→      // fn main()이 있는 경우 constructor attribute로 자동 초기화
   119→      const initFn = Array.from(this.pyAliasMap.keys())
   120→        .map(alias => `__fl_py_init_${alias}();`)
   121→        .join(' ');
   122→      mainWrapper = `\n__attribute__((constructor))\nstatic void __fl_py_auto_init(void) { ${initFn} }\n` +
   123→        `__attribute__((destructor))\nstatic void __fl_py_auto_fini(void) { Py_Finalize(); }\n`;
   124→    }
   125→
   126→    const cWithMain = base.c
   127→      ? `#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n#include <math.h>\n\n${base.c}${mainWrapper}`
   128→      : '';
   129→
   130→    // Python 코드에 main 블록 추가
   131→    const pyWithMain = base.python
   132→      ? `${base.python}\n\nif __name__ == '__main__':\n    pass\n`
   133→      : '';
   134→
   135→    return {
   136→      c: cWithMain,
   137→      python: pyWithMain,
   138→      mixed: base.mixed,
   139→      linkFlags: base.linkFlags,
   140→      externLibs: base.externLibs,
   141→    };
   142→  }
   143→
   144→  /**
   145→   * V 함수 → C 함수
   146→   * fn add(x: i64, y: i64) -> i64 { return x + y }
   147→   * →
   148→   * long long add(long long x, long long y) { return x + y; }
   149→   */
   150→  private genVFunction(fn: AST.VFunction): void {

