   150→  private genVFunction(fn: AST.VFunction): void {
   151→    // 반환타입 (main 함수는 항상 int)
   152→    const returnType = fn.name === 'main' ? 'int' : this.mapVType(fn.returnType || 'void');
   153→
   154→    // 파라미터 리스트
   155→    const paramList = fn.params.map((p) => `${this.mapVType(p.typeAnnotation || 'void')} ${p.name}`).join(', ');
   156→
   157→    // 함수 시그니처
   158→    this.writeC(`${returnType} ${fn.name}(${paramList}) {`);
   159→
   160→    // 함수 본문 (새 스코프: 파라미터 변수 등록)
   161→    this.indentLevel++;
   162→    this.declaredVars.push(new Set(fn.params.map(p => p.name)));
   163→    for (const stmt of fn.body) {
   164→      this.genVStatement(stmt);
   165→    }
   166→    this.declaredVars.pop();
   167→    this.indentLevel--;
   168→
   169→    this.writeC('}');
   170→    this.writeC(''); // 빈 줄
   171→  }
   172→
   173→  /**
   174→   * Python 함수 → Python 함수
   175→   * def slow(items): return items
   176→   * →
   177→   * def slow(items):
   178→   *     return items
   179→   */
   180→  private genPyFunction(fn: AST.PyFunction): void {
   181→    // 파라미터 리스트
   182→    const paramList = fn.params.map((p) => p.name).join(', ');
   183→
   184→    // 함수 정의
   185→    this.writePy(`def ${fn.name}(${paramList}):`);
   186→
   187→    // 함수 본문 (들여쓰기 필요)
   188→    this.indentLevel++;
   189→    for (const stmt of fn.body) {
   190→      this.genPyStatement(stmt);
   191→    }
   192→    this.indentLevel--;
   193→
   194→    this.writePy(''); // 빈 줄
   195→  }
   196→
   197→  /**
   198→   * @call 지시문 → 언어별 FFI/stub 코드 생성 (버스 터미널)
   199→   *
   200→   * python:pkg  → Python C API embed stub
   201→   * rust:pkg    → Rust cbindgen extern 선언
   202→   * go:pkg      → CGo extern 선언
   203→   * julia:pkg   → Julia C API stub
   204→   * js:pkg      → QuickJS / Node N-API stub
   205→   * c:lib       → #include + extern 선언
   206→   * cpp:lib     → extern "C" { } 래퍼
   207→   */
   208→  /**
   209→   * 알려진 C 라이브러리 → 링크 플래그 맵
   210→   * 추가가 필요하면 여기에만 넣으면 됨
   211→   */
   212→  private static readonly C_LINK_FLAGS: Record<string, string[]> = {
   213→    // 수학
   214→    'm':        ['-lm'],
   215→    'math':     ['-lm'],
   216→    // DB
   217→    'sqlite3':  ['-lsqlite3'],
   218→    // 네트워크
   219→    'curl':     ['-lcurl'],
   220→    'ssl':      ['-lssl', '-lcrypto'],
   221→    'openssl':  ['-lssl', '-lcrypto'],
   222→    // 압축
   223→    'zlib':     ['-lz'],
   224→    'z':        ['-lz'],
   225→    // 스레드
   226→    'pthread':  ['-lpthread'],
   227→    // 정규식
   228→    'pcre':     ['-lpcre'],
   229→    'pcre2':    ['-lpcre2-8'],
   230→    // UI
   231→    'ncurses':  ['-lncurses'],
   232→    // JSON
   233→    'jansson':  ['-ljansson'],
   234→    'cjson':    ['-lcjson'],
   235→    // 기타
   236→    'readline': ['-lreadline'],
   237→    'dl':       ['-ldl'],
   238→    'rt':       ['-lrt'],
   239→  };
   240→
   241→  private genExternCall(node: AST.ExternCall): void {
   242→    const alias = node.alias || this.safeAlias(node.package);
   243→    const ver = node.version ? ` v${node.version}` : '';
   244→
   245→    // 링크 플래그 수집
   246→    const flags = this.collectLinkFlags(node);
   247→    const libInfo: ExternLibInfo = {
   248→      lang: node.lang,
   249→      package: node.package,
   250→      version: node.version,
   251→      alias: node.alias,
   252→      linkFlags: flags,
   253→    };
   254→    flags.forEach(f => this.linkFlagsSet.add(f));
   255→    this.externLibs.push(libInfo);
   256→
   257→    this.writeC(`/* ── @call ${node.lang}:${node.package}${ver} ── */`);
   258→
   259→    switch (node.lang) {
   260→      case 'python': {
   261→        const cVar = `__fl_py_mod_${alias}`;
   262→        // alias 등록: np → { pkg: 'numpy', cVar: '__fl_py_mod_np' }
   263→        this.pyAliasMap.set(alias, { pkg: node.package, cVar });
   264→
   265→        // 마샬링 헬퍼는 첫 번째 python @call 에서만 주입
   266→        if (!this.pyHelpersInjected) {
   267→          this.pyHelpersInjected = true;
   268→          this.writeC(`/* ── FreeLang Python Bridge ── */`);
   269→          this.writeC(`#include <Python.h>`);
   270→          this.writeC(`/* --- 마샬링 헬퍼 --- */`);
   271→          this.writeC(`static long long __fl_py_to_ll(PyObject* o) {`);
   272→          this.writeC(`    if (!o) return 0;`);
   273→          this.writeC(`    long long v = PyLong_AsLongLong(o);`);
   274→          this.writeC(`    Py_DECREF(o); return v;`);
   275→          this.writeC(`}`);
   276→          this.writeC(`static double __fl_py_to_dbl(PyObject* o) {`);
   277→          this.writeC(`    if (!o) return 0.0;`);
   278→          this.writeC(`    double v = PyFloat_AsDouble(o);`);
   279→          this.writeC(`    Py_DECREF(o); return v;`);
   280→          this.writeC(`}`);
   281→          this.writeC(`static const char* __fl_py_to_str(PyObject* o) {`);
   282→          this.writeC(`    if (!o) return "";`);
   283→          this.writeC(`    const char* v = PyUnicode_AsUTF8(o);`);
   284→          this.writeC(`    Py_DECREF(o); return v ? v : "";`);
   285→          this.writeC(`}`);
   286→          this.writeC(`static void __fl_py_ensure_init(void) {`);
   287→          this.writeC(`    if (!Py_IsInitialized()) { Py_Initialize(); }`);
   288→          this.writeC(`}`);
   289→          this.writeC('');
   290→        }
   291→
   292→        // 모듈 로더
   293→        this.writeC(`/* @call python:${node.package} as ${alias} */`);
   294→        this.writeC(`/* Install: pip install ${node.package}${node.version ? `==${node.version}` : ''} */`);
   295→        this.writeC(`static PyObject* ${cVar} = NULL;`);
   296→        this.writeC(`static void __fl_py_init_${alias}(void) {`);
   297→        this.writeC(`    __fl_py_ensure_init();`);
   298→        this.writeC(`    ${cVar} = PyImport_ImportModule("${node.package}");`);
   299→        this.writeC(`    if (!${cVar}) { PyErr_Print(); fprintf(stderr, "Failed: ${node.package}\\n"); }`);
   300→        this.writeC(`}`);
   301→        this.writeC('');
   302→
   303→        // Python 쪽에는 일반 import
   304→        this.writePy(`import ${node.package}${node.alias ? ` as ${node.alias}` : ''}`);
   305→        break;
   306→      }
   307→
   308→      case 'rust': {
   309→        // Rust cbindgen: cargo build → libXXX.a → extern C
   310→        this.writeC(`/* Rust FFI: extern crate ${node.package} */`);
   311→        this.writeC(`/* Install: cargo add ${node.package}${node.version ? `@${node.version}` : ''} */`);
   312→        this.writeC(`/* Build:   cargo build --release && cbindgen --output ${alias}_bindings.h */`);
   313→        this.writeC(`/* Link:    gcc ... -L./target/release -l${alias} */`);
   314→        this.writeC(`/* --- Rust FFI stub BEGIN --- */`);
   315→        this.writeC(`#ifdef __has_include`);
   316→        this.writeC(`#  if __has_include("${alias}_bindings.h")`);
   317→        this.writeC(`#    include "${alias}_bindings.h"`);
   318→        this.writeC(`#  endif`);
   319→        this.writeC(`#endif`);
   320→        this.writeC(`/* extern declarations from ${node.package} go here after cbindgen */`);
   321→        this.writeC(`/* --- Rust FFI stub END --- */`);
   322→        this.writeC('');
   323→        break;
   324→      }
   325→
   326→      case 'go': {
   327→        // Go cgo: build shared lib → extern
   328→        const libName = alias.replace(/[^a-zA-Z0-9_]/g, '_');
   329→        this.writeC(`/* Go FFI: ${node.package} */`);
