   532→        this.writeC(`${this.indent()}return;`);
   533→      }
   534→    } else if (s.type === 'Break') {
   535→      this.writeC(`${this.indent()}break;`);
   536→    } else if (s.type === 'Continue') {
   537→      this.writeC(`${this.indent()}continue;`);
   538→    } else if (s.type === 'Assign') {
   539→      const assignStmt = s as AST.AssignStatement;
   540→      const value = assignStmt.value as any;
   541→      const varName = assignStmt.name;
   542→
   543→      // 현재 스코프(또는 상위 스코프)에서 이미 선언된 변수인지 확인
   544→      const alreadyDeclared = this.declaredVars.some(scope => scope.has(varName));
   545→
   546→      if (alreadyDeclared) {
   547→        // 재할당: 타입 선언 없이 그냥 대입
   548→        const expr = this.genVExpression(assignStmt.value);
   549→        this.writeC(`${this.indent()}${varName} = ${expr};`);
   550→      } else {
   551→        // 최초 선언: 현재 스코프에 등록
   552→        this.declaredVars[this.declaredVars.length - 1].add(varName);
   553→
   554→        // 명시적 타입 어노테이션이 있는 경우
   555→        if (assignStmt.typeAnnotation) {
   556→          const ta = assignStmt.typeAnnotation;
   557→          if (ta.endsWith('[]')) {
   558→            const elemType = this.mapVType(ta.slice(0, -2));
   559→            const expr = this.genVExpression(assignStmt.value);
   560→            if (value.type === 'Array') {
   561→              const len = (value as AST.ArrayLiteral).elements.length;
   562→              this.writeC(`${this.indent()}${elemType} ${varName}[${len}] = ${expr};`);
   563→            } else {
   564→              this.writeC(`${this.indent()}${elemType}* ${varName} = ${expr};`);
   565→            }
   566→          } else {
   567→            const cType = this.mapVType(ta);
   568→            const expr = this.genVExpression(assignStmt.value);
   569→            this.writeC(`${this.indent()}${cType} ${varName} = ${expr};`);
   570→          }
   571→        } else {
   572→          // 타입 추론: 값 기반
   573→          const expr = this.genVExpression(assignStmt.value);
   574→          let cType = 'long long';
   575→          if (value.type === 'String') {
   576→            cType = 'char*';
   577→          } else if (value.type === 'Array') {
   578→            const arrLit = value as AST.ArrayLiteral;
   579→            const firstElem = arrLit.elements[0] as any;
   580→            let elemType = 'long long';
   581→            if (firstElem?.type === 'String') elemType = 'char*';
   582→            else if (firstElem?.type === 'Number' && String(firstElem.value).includes('.')) elemType = 'double';
   583→            const len = arrLit.elements.length;
   584→            this.writeC(`${this.indent()}${elemType} ${varName}[${len}] = ${expr};`);
   585→            return;
   586→          } else if (value.type === 'Number' && String(value.value).includes('.')) {
   587→            cType = 'double';
   588→          } else if (value.type === 'StructLiteral') {
