   653→
   654→      this.indentLevel++;
   655→      this.declaredVars.push(new Set([forStmt.variable]));
   656→      for (const stmt of forStmt.body) {
   657→        this.genVStatement(stmt);
   658→      }
   659→      this.declaredVars.pop();
   660→      this.indentLevel--;
   661→      this.writeC(`${this.indent()}}`);
   662→    } else if (s.type === 'MatchStatement') {
   663→      // match x { case 1 => { ... } case _ => { ... } }
   664→      // → switch (x) { case 1: { ... break; } default: { ... break; } }
   665→      const matchStmt = s as AST.MatchStatement;
   666→      const subj = this.genVExpression(matchStmt.subject);
   667→      this.writeC(`${this.indent()}switch (${subj}) {`);
