     2→ * FreeLang Nexus - End-to-End FFI 실제 실행 테스트
     3→ *
     4→ * FreeLang 소스 → Codegen → C 컴파일 → 실행까지 전체 파이프라인 검증
     5→ * 각 언어 환경이 없으면 자동 skip
     6→ */
     7→
     8→import { NexusLexer } from '../src/nexus/lexer/nexus-lexer';
     9→import { NexusParser } from '../src/nexus/parser/nexus-parser';
    10→import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';
    11→import { NexusRunner } from '../src/nexus/runtime/nexus-runner';
    12→import { execSync } from 'child_process';
    13→
    14→// ─── 환경 감지 헬퍼 ─────────────────────────────────────────────────────────
    15→
    16→function hasCmd(cmd: string): boolean {
    17→  try { execSync(`which ${cmd}`, { stdio: 'pipe' }); return true; }
    18→  catch { return false; }
    19→}
    20→function hasPython(): boolean {
    21→  try { execSync('python3 -c "import sys"', { stdio: 'pipe' }); return true; }
    22→  catch { return false; }
    23→}
    24→function hasNumpy(): boolean {
    25→  try { execSync('python3 -c "import numpy"', { stdio: 'pipe' }); return true; }
    26→  catch { return false; }
    27→}
    28→function hasJulia(): boolean { return hasCmd('julia') && hasCmd('julia-config'); }
    29→function hasRust(): boolean { return hasCmd('cargo'); }
    30→function hasGo(): boolean { return hasCmd('go'); }
    31→
    32→// ─── 파이프라인 실행 헬퍼 ────────────────────────────────────────────────────
    33→
    34→function runFreeLang(src: string): { output: string; errors: string[] } {
    35→  const tokens = new NexusLexer(src).tokenize();
    36→  const ast    = new NexusParser(tokens).parse();
    37→  const result = new NexusCodegen().generateProgram(ast);
    38→  const runner = new NexusRunner();
    39→  const run    = runner.run(result);
    40→  return { output: run.cOutput, errors: run.errors };
    41→}
