   755→  /**
   756→   * V 표현식 생성 (C 코드용)
   757→   */
   758→  private genVExpression(expr: AST.Expression): string {
   759→    const e = expr as any;
   760→
   761→    if (e.type === 'Number') {
   762→      return (e as AST.NumberLiteral).value.toString();
   763→    }
   764→
   765→    if (e.type === 'String') {
   766→      // StringLiteral.value는 이미 따옴표를 포함 ("text" 형태)
   767→      return (e as AST.StringLiteral).value;
   768→    }
   769→
   770→    if (e.type === 'Identifier') {
   771→      return (e as AST.Identifier).name;
   772→    }
   773→
   774→    if (e.type === 'BinaryExpr') {
   775→      const binExpr = e as AST.BinaryExpr;
   776→      const left = this.genVExpression(binExpr.left);
   777→      const right = this.genVExpression(binExpr.right);
   778→      return `${left} ${binExpr.operator} ${right}`;
   779→    }
   780→
   781→    if (e.type === 'Array') {
   782→      const arrayLit = e as AST.ArrayLiteral;
   783→      const elements = arrayLit.elements.map((el) => this.genVExpression(el)).join(', ');
   784→      return `{${elements}}`;
   785→    }
   786→
   787→    if (e.type === 'ArrayAccess') {
   788→      const arrayAccess = e as AST.ArrayAccess;
   789→      const obj = this.genVExpression(arrayAccess.object);
   790→      const idx = this.genVExpression(arrayAccess.index);
   791→      return `${obj}[${idx}]`;
   792→    }
   793→
   794→    if (e.type === 'Call') {
   795→      const callExpr = e as AST.CallExpr;
   796→
   797→      // Python alias.method(args) → PyObject_CallMethod 변환
   798→      // 예: np.zeros(3) → __fl_py_to_ll(PyObject_CallMethod(__fl_py_mod_np, "zeros", "L", 3))
   799→      const calleeNode = callExpr.callee as any;
   800→      if (calleeNode && calleeNode.type === 'MemberAccess') {
   801→        const maNode = calleeNode as AST.MemberAccess;
   802→        const objNode = maNode.object as any;
   803→        if (objNode && objNode.type === 'Identifier') {
   804→          const alias = objNode.name;
   805→          if (this.pyAliasMap.has(alias)) {
   806→            const info = this.pyAliasMap.get(alias)!;
   807→            const method = maNode.property;
   808→            const args = callExpr.args;
   809→            return this.genPyMethodCall(info.cVar, method, args);
   810→          }
   811→        }
   812→      }
   813→
   814→      // callee가 Identifier인 경우 함수명 추출
   815→      let calleeStr: string | null = null;
   816→      if (typeof callExpr.callee === 'string') {
   817→        calleeStr = callExpr.callee;
   818→      } else {
   819→        const calleeExpr = callExpr.callee as any;
   820→        if (calleeExpr.type === 'Identifier') {
   821→          calleeStr = calleeExpr.name;
   822→        }
   823→      }
   824→
   825→      // V 내장 함수 처리
   826→      if (calleeStr && this.V_BUILTINS.has(calleeStr)) {
   827→        return this.genVBuiltinCall(calleeStr, callExpr.args);
   828→      }
   829→
   830→      // 일반 함수 호출
   831→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genVExpression(callExpr.callee);
   832→      const args = callExpr.args.map((arg) => this.genVExpression(arg)).join(', ');
   833→      return `${callee}(${args})`;
   834→    }
   835→
   836→    if (e.type === 'MemberAccess') {
   837→      const ma = e as AST.MemberAccess;
   838→      const obj = this.genVExpression(ma.object);
   839→      if (ma.property === 'length') {
   840→        // C에는 .length가 없으므로 sizeof 패턴 생성
   841→        return `(sizeof(${obj})/sizeof(${obj}[0]))`;
   842→      }
   843→      return `${obj}.${ma.property}`;
   844→    }
   845→
   846→    if (e.type === 'StructLiteral') {
   847→      const sl = e as AST.StructLiteral;
   848→      const entries = Object.entries(sl.fields);
   849→      const fieldsCode = entries.map(([k, v]) => `.${k} = ${this.genVExpression(v)}`).join(', ');
   850→      return `(${sl.name}){${fieldsCode}}`;
   851→    }
   852→
   853→    return '';
   854→  }
