   856→  /**
   857→   * Python alias.method(args) → PyObject_CallMethod C 호출 생성
   858→   * 예: np.zeros(3) → __fl_py_to_ll(PyObject_CallMethod(__fl_py_mod_np, "zeros", "L", (long long)3))
   859→   * 반환 타입은 컨텍스트로 알 수 없어 기본 __fl_py_to_ll 래퍼 사용
   860→   */
   861→  private genPyMethodCall(cVar: string, method: string, args: AST.Expression[]): string {
   862→    if (args.length === 0) {
   863→      // 인수 없는 경우: PyObject_CallMethod(obj, "method", NULL)
   864→      return `__fl_py_to_ll(PyObject_CallMethod(${cVar}, "${method}", NULL))`;
   865→    }
   866→    // 인수 있는 경우: PyObject_CallMethodObjArgs 또는 format string 방식
   867→    // 간단히 format string "O" per arg, 각 arg를 PyLong_FromLongLong으로 감쌈
   868→    const fmtChars = args.map(a => {
   869→      const ea = a as any;
   870→      if (ea.type === 'String') return 's';
   871→      return 'L';  // long long
   872→    }).join('');
   873→
   874→    const argExprs = args.map(a => {
   875→      const ea = a as any;
   876→      if (ea.type === 'String') {
   877→        // 문자열: 따옴표 제거한 raw 값
   878→        return ea.value.slice(1, -1);
   879→      }
   880→      return `(long long)(${this.genVExpression(a)})`;
   881→    }).join(', ');
   882→
   883→    return `__fl_py_to_ll(PyObject_CallMethod(${cVar}, "${method}", "${fmtChars}", ${argExprs}))`;
   884→  }
