   889→  private genVBuiltinCall(name: string, args: AST.Expression[]): string {
   890→    if (name === 'println') {
   891→      if (args.length === 0) return 'printf("\\n")';
   892→      const firstArg = args[0] as any;
   893→      // StringLiteral인 경우: printf의 format string으로 사용
   894→      if (firstArg.type === 'String') {
